        background: Color(hex: "#ffffff"), surface: Color(hex: "#ffffff"), surfaceRaised: Color(hex: "#ffffff"), surfaceMuted: Color(hex: "#f8f8f8"),
        foreground: Color(hex: "#0b0b0b"), textSecondary: Color(hex: "#585858"), textMuted: Color(hex: "#7d7d7d"),
        border: Color(hex: "#e9e9e9"), borderSubtle: Color(hex: "#f3f3f3"), borderStrong: Color(hex: "#c4c4c4"),
        accent: Color(hex: "#353535"), accentStrong: Color(hex: "#1f1f1f"), accentSubtle: Color(hex: "#353535", opacity: 0.1), accentForeground: Color(hex: "#ffffff"),
        success: Color(hex: "#007b12"), warning: Color(hex: "#b66400"), danger: Color(hex: "#cd1526"),
        controlOn: Color(hex: "#1d1d1d"), controlGlyph: Color(hex: "#ffffff"), controlFill: Color(hex: "#1d1d1d"), controlTrack: Color(hex: "#dcdcdc"), controlThumb: Color(hex: "#ffffff"), controlThumbOn: Color(hex: "#ffffff"),
        series: [Color(hex: "#1f7dcf"), Color(hex: "#7128a5"), Color(hex: "#e58f00"), Color(hex: "#009e84")]
